import{_ as t,l as n,o as e,c as o,v as r,p as l,x as i,d as E,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"三代危机模型","description":"","frontmatter":{"title":"三代危机模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/crisis-generations.md","filePath":"econ/crisis-generations.md","lastUpdated":1789023840000}'),p={name:"econ/crisis-generations.md"};function A(h,a,B,m,_,u){const s=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="三代危机模型" tabindex="-1">三代危机模型 <a class="header-anchor" href="#三代危机模型" aria-label="Permalink to &quot;三代危机模型&quot;">​</a></h1><div class="epigraph"><p>第一代是基本面算术；第二代是多重均衡与政策权衡；第三代是资产负债表与金融加速器。同一场贬值，三套机制可以叠，不要用一代否证另一代。</p><footer>—— Obstfeld, Models of Currency Crises with Self-Fulfilling Features, EER 1996；Chang and Velasco；Krugman 1999 资产负债表</footer></div><p><a href="/econ/currency-crisis-models">上一课</a>把第一代 \\(T\\) 钉死。本课缺口是谱系：为何储备仍多也会倒（第二代），为何贬值变成产出崩溃（第三代）。资本管制下一课是政策工具。本课分代，接到<a href="/econ/original-sin">原罪</a>与<a href="/econ/sudden-stop">突然停止</a>，不写成编年史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一代：政策规则与钉住逻辑不一致，时点唯一。第二代（Obstfeld）：政府有反应函数，守钉住的成本随失业、利率上升；投机加息提高成本，可以有两个均衡——大家信守则守、信破则破。基本面在「灰色区」时，太阳黑子或协调决定。第三代：外币债、银行期限错配，贬值摧毁净值，信贷收缩验证危机（Krugman 1999；Chang–Velasco 国际流动性）。缺口是：1992 年英镑、1997 年亚洲、1998 年俄罗斯不能用同一条储备曲线讲完。</p><p><span class="marginnote">灰色区：基本面足够好则唯一守住，足够差则唯一崩溃，中间才有多重均衡。第二代不是「任意恐慌」，是区间里的协调。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三列：驱动、时点、产出。第一代产出可以不大动（货币改锚）。第二代：防御加息本身制造衰退，政府放弃。第三代：净值通道使 \\(Y\\) 崩溃，贬值的教科书支出转换被盖住。政策：第一代改财政货币规则；第二代要承诺装置（货币局、美元化、或提高退出成本）；第三代要审慎、币种匹配、国际最后贷款人——后课互换线。</p>',8)),(e(),l(c,null,{default:i(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22%E7%AC%AC%E4%B8%80%E4%BB%A3%3A%20%E8%A7%84%E5%88%99%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%20--%3E%20T%5B%22%E5%94%AF%E4%B8%80%E6%97%B6%E7%82%B9%20T%22%5D%0A%20%20G2%5B%22%E7%AC%AC%E4%BA%8C%E4%BB%A3%3A%20%E6%9D%83%E8%A1%A1%20%2B%20%E5%8D%8F%E8%B0%83%22%5D%20--%3E%20MULT%5B%22%E7%81%B0%E8%89%B2%E5%8C%BA%E5%A4%9A%E9%87%8D%E5%9D%87%E8%A1%A1%22%5D%0A%20%20G3%5B%22%E7%AC%AC%E4%B8%89%E4%BB%A3%3A%20%E9%94%99%E9%85%8D%20%2B%20%E9%93%B6%E8%A1%8C%22%5D%20--%3E%20Y%5B%22Y%20%E5%B4%A9%E6%BA%83%22%5D%0A%20%20SS%5B%22%E7%AA%81%E7%84%B6%E5%81%9C%E6%AD%A2%22%5D%20--%3E%20G3%0A%20%20OSIN%5B%22%E5%8E%9F%E7%BD%AA%22%5D%20--%3E%20G3%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与分担：危机是保险该赔付时资本流出，符号反了。第二代的「预言自我实现」是协调失败，不是 Backus–Smith 的慢谜。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制分层。第一代：库存耗尽。第二代：最优停时与战略互补（别人跑，我更该跑，政府更难守）。第三代：抵押约束，\\(E\\) 进净值，火线出售放大——主干<a href="/econ/fire-sales">火线出售</a>在开放下加币种。三套可以叠：财政软（一）、防御代价高（二）、银行外币债（三）。</p><p>欧洲 1992：英国基本面不是拉美财政崩溃，更像第二代。亚洲 1997：储备表面上够，公司与银行错配，第三代。第一代仍适用于明确用铸币税补赤字的钉住。</p><p><span class="marginnote">Morris–Shin 全球博弈给第二代加噪声，可以选出唯一均衡，但仍对基本面极敏感。本课标存在，不推噪声代数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某次危机「定性为第几代」当作研究完成。不写投机者操作手册。下一课资本管制：可以推迟第一代的 \\(T\\)、提高第二代攻击成本、在第三代时当紧急闸。欧债后课是货币同盟内的第三代变体（无独立 \\(E\\)）。不要用三代取消三角：每一代都是三角被压时的一种破裂形式。</p><p>后课默认：一代基本面时点、二代灰色区协调、三代净值加速器。政策工具不同。突然停止与原罪是第三代的宏观零件。管制下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>第一代：不一致规则，唯一 \\(T\\)。</li><li>第二代：守住成本内生，灰色区多重均衡。</li><li>第三代：币种与期限错配，贬值验证信贷崩溃。</li><li>可叠加；用一代否证另一代是类别错误。</li><li>出处：Obstfeld, <em>EER</em> 1996；Chang and Velasco；Krugman 1999。</li></ul>',10))])}const T=t(p,[["render",A]]);export{C as __pageData,T as default};
